head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[header > P > tooltipLocaleRef]<br/>클라이언트 다국어가 적용되었을 때 tooltip 속성의 툴팁에 표시할 텍스트의 Key 값을 설정합니다.",
    "validation" : [
        "툴팁에 표시할 다국어 텍스트의 Key 값을 설정합니다.",
        "속성값은 참고용으로 사용되며 실제 툴팁은 Header Cell 값과 GridView 의 관련 속성을 설정해야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    con_tooltipLocaleRef.setValue("websquare_name");

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 조건 설정
    //  - tooltipLocaleRef 는 header(Header 영역) 단위 속성이며 dynamic N 이므로 렌더 시점에만 설정한다.
    //  - 툴팁 표시 전제로 GridView 는 useLocale / tooltipHeader / tooltipHeaderShowAlways 를 고정 설정하고,
    //    Header Cell 값(name1 ~ name4)과 header 의 tooltip 원문은 고정한다.
    let cRef = con_tooltipLocaleRef.getValue();
    let lblRef = (cRef === '') ? '미설정' : cRef;
    let attrRef = (cRef === '') ? '' : ' tooltipLocaleRef="' + cRef + '"';

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 클라이언트 다국어 적용 상태 (config language=ko, /lang/ko.js 로드) + GridView useLocale=true, tooltipHeader=true, tooltipHeaderShowAlways=true\n[전제] w2:header 의 tooltip 은 (헤더 영역 툴팁 원문) 으로 고정하고 tooltipLocaleRef 만 옵션으로 변경\n[현재] header tooltipLocaleRef = ' + lblRef + '\n[절차] 옵션 변경 후 Target 재생성 -> Header Cell(name1 ~ name4) 위로 마우스 이동 -> (선언값 확인) 버튼 클릭\n[확인] hover 시 실제로 표시된 툴팁 텍스트, 선언한 Key 값과 그 Key 의 다국어 텍스트를 결과창에서 확인"', '', 'label1');

    // dataList 생성 (col1~col4 / 4행)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성 (header 에 tooltipLocaleRef 설정)
    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" useLocale="true" tooltipHeader="true" tooltipHeaderShowAlways="true" ev:onheadermouseover="scwin.target1_onheadermouseover" id="" style="width:600px;height:220px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1" tooltip="헤더 영역 툴팁 원문"' + attrRef + '>';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column1" value="name1"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column2" value="name2"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column3" value="name3"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column4" value="name4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 렌더된 Header 영역 요소 조회 (엔진은 Header 영역을 thead 로 렌더)
scwin.getHeaderArea = function () {
    return target1.render.querySelector("[id$='_head_table']");
}



// Header Cell 마우스 오버 시 실제로 표시되는 툴팁 확인
scwin.target1_onheadermouseover = function (info) {
    let bottom = wf_body_bottom.getObj("scwin");
    let th = (info && info.id) ? document.querySelector("#" + info.id) : null;

    bottom.setReturnValue("[hover] Header Cell 값 : " + (th ? th.textContent.trim() : '-'));

    $c.gcm.getTooltipInfo(wf_body_bottom);
}



// header 에 설정한 tooltipLocaleRef 선언값과 다국어 텍스트 확인
scwin.btn_checkLocaleRef_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");

    let cRef = con_tooltipLocaleRef.getValue();
    let localeText = cRef ? target1.getLocaleValue(cRef) : "";

    let headArea = scwin.getHeaderArea();
    let structAttr = (target1.struct && target1.struct.head && target1.struct.head.attr) ? target1.struct.head.attr.tooltipLocaleRef : undefined;
    let domAttr = headArea ? headArea.getAttribute("data-tooltipLocaleRef") : null;

    bottom.setReturnValue("[선언] header tooltipLocaleRef : " + (cRef === '' ? '(미설정)' : cRef) + " / 해당 Key 의 다국어 텍스트 : " + (localeText ? localeText : '(없음)'));
    bottom.setReturnValue("[반영] struct.head.attr.tooltipLocaleRef : " + ((structAttr === undefined || structAttr === null) ? '(없음)' : structAttr) + " / Header 영역 요소 속성 : " + (domAttr === null ? '(없음)' : domAttr));
}
